-- BioPrep: complete database setup in one file. Paste into Supabase > SQL Editor and click Run, ONCE, on a fresh project.
-- This is every file in supabase/migrations, in order. Generated by: npm run gen:setup-sql

-- ===== supabase/migrations/20260101000100_core_schema.sql =====
-- BioPrep core schema.
-- Design rules
--   * Anything a student must not see before finishing the tutor session (correct answer, explanation, whys,
--     video path, Socratic keys/hints) lives in tables that students cannot read: question_secrets, socratic_steps.
--   * Students never write scores, unlocks or free-use rows directly. Scoring and entitlement run in SECURITY DEFINER
--     functions or in the API (service role).
--   * Helpers live in the `private` schema, which PostgREST does not expose.

create schema if not exists private;

create type public.user_role as enum ('student', 'teacher', 'admin');
create type public.question_status as enum ('draft', 'published');

-- ---------------------------------------------------------------- profiles
create table public.profiles (
  id          uuid primary key references auth.users (id) on delete cascade,
  role        public.user_role not null default 'student',
  name        text not null default '' check (char_length(name) <= 80),
  phone       text,
  exam_year   int check (exam_year between 2025 and 2040),
  language    text not null default 'en' check (language in ('en', 'hi', 'mni')),
  onboarded   boolean not null default false,
  created_at  timestamptz not null default now()
);

-- Role helpers. SECURITY DEFINER so policies on profiles itself cannot recurse.
create function private.app_role() returns public.user_role
language sql stable security definer set search_path = '' as $$
  select coalesce((select p.role from public.profiles p where p.id = auth.uid()), 'student'::public.user_role)
$$;
create function private.is_staff() returns boolean
language sql stable security definer set search_path = '' as $$
  select private.app_role() in ('teacher', 'admin')
$$;
create function private.is_admin() returns boolean
language sql stable security definer set search_path = '' as $$
  select private.app_role() = 'admin'
$$;

-- A profile row is created for every new auth user. Role is never taken from client-supplied metadata.
create function private.handle_new_user() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.profiles (id, phone) values (new.id, new.phone) on conflict (id) do nothing;
  return new;
end $$;
create trigger on_auth_user_created after insert on auth.users
  for each row execute function private.handle_new_user();

create function private.touch_updated_at() returns trigger
language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;

-- ---------------------------------------------------------------- questions
-- Public part: safe to show while a student is taking the test.
create table public.questions (
  id          uuid primary key default gen_random_uuid(),
  subject     text not null check (subject in ('Botany', 'Zoology', 'Physics', 'Chemistry')),
  chapter     text not null check (char_length(chapter) between 1 and 200),
  difficulty  text not null default 'Medium' check (difficulty in ('Easy', 'Medium', 'Hard')),
  text        text not null check (char_length(text) between 1 and 2000),
  options     jsonb not null check (jsonb_typeof(options) = 'array' and jsonb_array_length(options) = 4),
  image_path  text,
  option_style text not null default 'ABCD' check (option_style in ('ABCD', 'abcd', '1234', 'roman', 'ROMAN', 'hindi')),
  image_alt   text check (char_length(image_alt) <= 300),
  status      public.question_status not null default 'draft',
  created_by  uuid references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index questions_status_idx on public.questions (status, subject);
create trigger questions_touch before update on public.questions
  for each row execute function private.touch_updated_at();

-- Secret part: correct answer, explanation, video. Students have no policy here.
create table public.question_secrets (
  question_id  uuid primary key references public.questions (id) on delete cascade,
  correct      smallint not null check (correct between 0 and 3),
  explanation  text not null default '',
  why_wrong    jsonb not null default '[]'::jsonb,
  recap        jsonb not null default '{}'::jsonb,
  ncert        text not null default '',
  caption      text not null default '',
  video_path   text
);

-- Guiding questions for the Socratic tutor (2 to 3 per question). Keys, hints and `good` are secret prompts.
create table public.socratic_steps (
  id           uuid primary key default gen_random_uuid(),
  question_id  uuid not null references public.questions (id) on delete cascade,
  position     smallint not null check (position between 1 and 3),
  ask          text not null check (char_length(ask) between 1 and 500),
  keys         text[] not null default '{}',
  hint         text not null default '',
  good         text not null default '',
  sample       text not null default '',
  choices      text[] not null default '{}',
  unique (question_id, position)
);

-- ---------------------------------------------------------------- tests
create table public.tests (
  id                uuid primary key default gen_random_uuid(),
  title             text not null check (char_length(title) between 1 and 120),
  kind              text not null default 'Custom',
  duration_minutes  int not null default 10 check (duration_minutes between 1 and 600),
  price_inr         int not null default 100 check (price_inr >= 0),
  published         boolean not null default false,
  created_by        uuid references public.profiles (id) on delete set null,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
create trigger tests_touch before update on public.tests
  for each row execute function private.touch_updated_at();

create table public.test_questions (
  test_id      uuid not null references public.tests (id) on delete cascade,
  question_id  uuid not null references public.questions (id) on delete restrict,
  position     int not null check (position >= 1),
  primary key (test_id, question_id),
  unique (test_id, position) deferrable initially deferred
);

-- ---------------------------------------------------------------- attempts
create table public.attempts (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references public.profiles (id) on delete cascade,
  test_id       uuid not null references public.tests (id) on delete cascade,
  started_at    timestamptz not null default now(),
  submitted_at  timestamptz,
  correct       int,
  wrong         int,
  skipped       int,
  score         int,
  max_score     int
);
create index attempts_user_idx on public.attempts (user_id, started_at desc);
create index attempts_test_idx on public.attempts (test_id) where submitted_at is not null;

create table public.attempt_answers (
  attempt_id    uuid not null references public.attempts (id) on delete cascade,
  question_id   uuid not null references public.questions (id) on delete cascade,
  selected      smallint check (selected between 0 and 3), -- null = skipped
  is_correct    boolean,
  time_seconds  int not null default 0 check (time_seconds between 0 and 7200),
  primary key (attempt_id, question_id)
);
create index attempt_answers_question_idx on public.attempt_answers (question_id);

-- ---------------------------------------------------------------- entitlement tables
create table public.unlocks (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references public.profiles (id) on delete cascade,
  test_id     uuid not null references public.tests (id) on delete cascade,
  source      text not null default 'payment' check (source in ('payment', 'manual')),
  created_at  timestamptz not null default now(),
  revoked_at  timestamptz,
  unique (user_id, test_id)
);

create table public.free_explanation_uses (
  user_id      uuid not null references public.profiles (id) on delete cascade,
  question_id  uuid not null references public.questions (id) on delete cascade,
  created_at   timestamptz not null default now(),
  primary key (user_id, question_id)
);

create table public.revision_items (
  user_id      uuid not null references public.profiles (id) on delete cascade,
  question_id  uuid not null references public.questions (id) on delete cascade,
  created_at   timestamptz not null default now(),
  primary key (user_id, question_id)
);

-- ===== supabase/migrations/20260101000200_functions_rls.sql =====
-- Functions, row-level security and grants.

-- ---------------------------------------------------------------- limits
create function private.free_explanation_limit() returns int
language sql immutable as $$ select 2 $$; -- keep equal to FREE_EXPLANATIONS in shared/rules.js

-- Has this user submitted an attempt that contained this question? Gate for any explanation access.
create function private.has_attempted(p_user uuid, p_question uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1
    from public.attempts a
    join public.attempt_answers aa on aa.attempt_id = a.id
    where a.user_id = p_user and a.submitted_at is not null and aa.question_id = p_question
  )
$$;

-- Hard cap on free explanations, also enforced if a row is inserted through any other path.
create function private.guard_free_uses() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  perform pg_advisory_xact_lock(hashtext('free:' || new.user_id::text));
  if (select count(*) from public.free_explanation_uses f where f.user_id = new.user_id) >= private.free_explanation_limit() then
    raise exception 'free_limit_reached' using errcode = 'P0001';
  end if;
  return new;
end $$;
create trigger free_uses_guard before insert on public.free_explanation_uses
  for each row execute function private.guard_free_uses();

-- ---------------------------------------------------------------- student RPCs
create function public.complete_profile(p_name text, p_exam_year int) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if auth.uid() is null then raise exception 'not_authenticated' using errcode = '42501'; end if;
  update public.profiles
     set name = left(btrim(coalesce(p_name, '')), 80), exam_year = p_exam_year, onboarded = true
   where id = auth.uid();
end $$;

create function public.start_attempt(p_test uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  v_id uuid;
begin
  if v_uid is null then raise exception 'not_authenticated' using errcode = '42501'; end if;
  if not exists (select 1 from public.tests t where t.id = p_test and (t.published or private.is_staff())) then
    raise exception 'test_not_found' using errcode = 'P0002';
  end if;
  insert into public.attempts (user_id, test_id) values (v_uid, p_test) returning id into v_id;
  return v_id;
end $$;

-- Scores an attempt on the server. The client never sees correct answers, so it cannot score itself.
-- p_answers: {"<question_id>": 0..3}   p_times: {"<question_id>": seconds}
create function public.submit_attempt(p_attempt uuid, p_answers jsonb, p_times jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  v_att public.attempts%rowtype;
  v_minutes int;
  v_total int;
  v_correct int;
  v_wrong int;
begin
  if v_uid is null then raise exception 'not_authenticated' using errcode = '42501'; end if;
  select * into v_att from public.attempts where id = p_attempt and user_id = v_uid for update;
  if not found then raise exception 'attempt_not_found' using errcode = 'P0002'; end if;

  if v_att.submitted_at is null then
    select duration_minutes into v_minutes from public.tests where id = v_att.test_id;
    -- The client auto-submits at 00:00. Allow 5 minutes for slow networks, refuse anything later.
    if now() > v_att.started_at + make_interval(mins => v_minutes) + interval '5 minutes' then
      raise exception 'attempt_expired' using errcode = 'P0001';
    end if;

    insert into public.attempt_answers (attempt_id, question_id, selected, is_correct, time_seconds)
    select p_attempt, tq.question_id, sel.v,
           case when sel.v is null then null else sel.v = qs.correct end,
           case when (p_times ->> tq.question_id::text) ~ '^\d{1,5}(\.\d+)?$'
                then least(round((p_times ->> tq.question_id::text)::numeric)::int, 7200) else 0 end
    from public.test_questions tq
    join public.question_secrets qs on qs.question_id = tq.question_id
    cross join lateral (
      select case when (p_answers ->> tq.question_id::text) ~ '^[0-3]$'
                  then (p_answers ->> tq.question_id::text)::smallint end as v
    ) sel
    where tq.test_id = v_att.test_id;

    select count(*), count(*) filter (where is_correct), count(*) filter (where is_correct is false)
      into v_total, v_correct, v_wrong
      from public.attempt_answers where attempt_id = p_attempt;

    -- Marking scheme: +4 correct, -1 wrong, 0 skipped (MARKS in shared/rules.js).
    update public.attempts
       set submitted_at = now(), correct = v_correct, wrong = v_wrong, skipped = v_total - v_correct - v_wrong,
           score = v_correct * 4 - v_wrong, max_score = v_total * 4
     where id = p_attempt;
  end if;

  return (select jsonb_build_object('id', a.id, 'test_id', a.test_id, 'correct', a.correct, 'wrong', a.wrong,
                                    'skipped', a.skipped, 'score', a.score, 'max', a.max_score,
                                    'submitted_at', a.submitted_at)
            from public.attempts a where a.id = p_attempt);
end $$;

-- ---------------------------------------------------------------- staff RPCs
create function public.admin_upsert_question(p jsonb) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  v_id uuid := coalesce(nullif(p ->> 'id', '')::uuid, gen_random_uuid());
  v_status public.question_status := coalesce(nullif(p ->> 'status', ''), 'draft')::public.question_status;
  v_step jsonb;
  v_i int := 0;
  v_asks int;
begin
  if not private.is_staff() then raise exception 'forbidden' using errcode = '42501'; end if;

  if jsonb_typeof(p -> 'options') is distinct from 'array' or jsonb_array_length(p -> 'options') <> 4 then
    raise exception 'invalid_question: need exactly four options' using errcode = 'P0001';
  end if;

  if v_status = 'published' then
    if btrim(coalesce(p ->> 'text', '')) = '' or btrim(coalesce(p ->> 'chapter', '')) = '' then
      raise exception 'invalid_question: question text and chapter are required' using errcode = 'P0001';
    end if;
    if exists (select 1 from jsonb_array_elements_text(p -> 'options') o where btrim(o) = '') then
      raise exception 'invalid_question: all four options are required' using errcode = 'P0001';
    end if;
    if btrim(coalesce(p ->> 'explanation', '')) = '' then
      raise exception 'invalid_question: an explanation is required to publish' using errcode = 'P0001';
    end if;
    select count(*) into v_asks from jsonb_array_elements(coalesce(p -> 'socratic', '[]'::jsonb)) s
     where btrim(coalesce(s ->> 'ask', '')) <> '';
    if v_asks < 2 then
      raise exception 'invalid_question: add at least two guiding questions to publish' using errcode = 'P0001';
    end if;
  end if;

  insert into public.questions (id, subject, chapter, difficulty, text, options, option_style, image_path, image_alt, status, created_by)
  values (v_id, p ->> 'subject', btrim(coalesce(p ->> 'chapter', '')), coalesce(nullif(p ->> 'difficulty', ''), 'Medium'),
          btrim(coalesce(p ->> 'text', '')), p -> 'options', coalesce(nullif(p ->> 'optionStyle', ''), 'ABCD'), nullif(p ->> 'imagePath', ''), left(nullif(btrim(coalesce(p ->> 'imageAlt', '')), ''), 300), v_status, auth.uid())
  on conflict (id) do update
     set subject = excluded.subject, chapter = excluded.chapter, difficulty = excluded.difficulty, text = excluded.text,
         options = excluded.options, option_style = excluded.option_style, image_path = excluded.image_path, image_alt = excluded.image_alt, status = excluded.status;

  insert into public.question_secrets (question_id, correct, explanation, why_wrong, recap, ncert, caption, video_path)
  values (v_id, coalesce((p ->> 'correct')::int, 0), coalesce(p ->> 'explanation', ''),
          coalesce(p -> 'whyWrong', '[]'::jsonb), coalesce(p -> 'recap', '{}'::jsonb),
          coalesce(p ->> 'ncert', ''), coalesce(p ->> 'caption', ''), nullif(p ->> 'videoPath', ''))
  on conflict (question_id) do update
     set correct = excluded.correct, explanation = excluded.explanation, why_wrong = excluded.why_wrong,
         recap = excluded.recap, ncert = excluded.ncert, caption = excluded.caption, video_path = excluded.video_path;

  delete from public.socratic_steps where question_id = v_id;
  for v_step in select * from jsonb_array_elements(coalesce(p -> 'socratic', '[]'::jsonb)) loop
    continue when btrim(coalesce(v_step ->> 'ask', '')) = '';
    v_i := v_i + 1;
    exit when v_i > 3;
    insert into public.socratic_steps (question_id, position, ask, keys, hint, good, sample, choices)
    values (v_id, v_i, btrim(v_step ->> 'ask'),
            array(select jsonb_array_elements_text(coalesce(v_step -> 'keys', '[]'::jsonb))),
            coalesce(v_step ->> 'hint', ''), coalesce(v_step ->> 'good', ''), coalesce(v_step ->> 'sample', ''),
            array(select jsonb_array_elements_text(coalesce(v_step -> 'choices', '[]'::jsonb))));
  end loop;
  return v_id;
end $$;

-- Full question for the editor, including secrets. Staff only.
create function public.admin_get_question(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not private.is_staff() then raise exception 'forbidden' using errcode = '42501'; end if;
  return (
    select jsonb_build_object(
      'id', q.id, 'subject', q.subject, 'chapter', q.chapter, 'difficulty', q.difficulty, 'text', q.text,
      'options', q.options, 'optionStyle', q.option_style, 'imagePath', q.image_path, 'imageAlt', q.image_alt, 'status', q.status,
      'correct', s.correct, 'explanation', s.explanation, 'whyWrong', s.why_wrong, 'recap', s.recap,
      'ncert', s.ncert, 'caption', s.caption, 'videoPath', s.video_path,
      'socratic', (select coalesce(jsonb_agg(jsonb_build_object(
                     'ask', t.ask, 'keys', to_jsonb(t.keys), 'hint', t.hint, 'good', t.good,
                     'sample', t.sample, 'choices', to_jsonb(t.choices)) order by t.position), '[]'::jsonb)
                   from public.socratic_steps t where t.question_id = q.id))
    from public.questions q left join public.question_secrets s on s.question_id = q.id
    where q.id = p_id);
end $$;

create function public.admin_upsert_test(p jsonb) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  v_id uuid := coalesce(nullif(p ->> 'id', '')::uuid, gen_random_uuid());
  v_pub boolean := coalesce((p ->> 'published')::boolean, false);
  v_qids jsonb := coalesce(p -> 'qids', '[]'::jsonb);
begin
  if not private.is_staff() then raise exception 'forbidden' using errcode = '42501'; end if;
  if btrim(coalesce(p ->> 'title', '')) = '' then
    raise exception 'invalid_test: a title is required' using errcode = 'P0001';
  end if;
  if v_pub then
    if jsonb_array_length(v_qids) = 0 then
      raise exception 'invalid_test: add at least one question before publishing' using errcode = 'P0001';
    end if;
    if exists (select 1 from jsonb_array_elements_text(v_qids) x
               left join public.questions q on q.id = x::uuid
               where q.id is null or q.status <> 'published') then
      raise exception 'invalid_test: every question in a published test must be published' using errcode = 'P0001';
    end if;
  end if;

  insert into public.tests (id, title, kind, duration_minutes, price_inr, published, created_by)
  values (v_id, btrim(p ->> 'title'), coalesce(nullif(p ->> 'kind', ''), 'Custom'),
          coalesce((p ->> 'duration')::int, 10), coalesce((p ->> 'price')::int, 100), v_pub, auth.uid())
  on conflict (id) do update
     set title = excluded.title, kind = excluded.kind, duration_minutes = excluded.duration_minutes,
         price_inr = excluded.price_inr, published = excluded.published;

  delete from public.test_questions where test_id = v_id;
  insert into public.test_questions (test_id, question_id, position)
  select v_id, x::uuid, n from jsonb_array_elements_text(v_qids) with ordinality as t(x, n);
  return v_id;
end $$;

create function public.admin_set_role(p_user uuid, p_role public.user_role) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not private.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_user = auth.uid() then raise exception 'cannot change your own role' using errcode = 'P0001'; end if;
  update public.profiles set role = p_role where id = p_user;
end $$;

create function public.admin_grant_unlock(p_user uuid, p_test uuid) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not private.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  insert into public.unlocks (user_id, test_id, source) values (p_user, p_test, 'manual')
  on conflict (user_id, test_id) do update set revoked_at = null;
end $$;

-- ---------------------------------------------------------------- row-level security
alter table public.profiles             enable row level security;
alter table public.questions            enable row level security;
alter table public.question_secrets     enable row level security;
alter table public.socratic_steps       enable row level security;
alter table public.tests                enable row level security;
alter table public.test_questions       enable row level security;
alter table public.attempts             enable row level security;
alter table public.attempt_answers      enable row level security;
alter table public.unlocks              enable row level security;
alter table public.free_explanation_uses enable row level security;
alter table public.revision_items       enable row level security;

-- profiles: read your own row (admins read all). Update only name/exam_year/language (column grant below).
create policy profiles_select on public.profiles for select to authenticated
  using (id = auth.uid() or private.is_admin());
create policy profiles_update on public.profiles for update to authenticated
  using (id = auth.uid()) with check (id = auth.uid());

-- questions: students read published only; staff read and write everything.
create policy questions_student_read on public.questions for select to authenticated
  using (status = 'published');
create policy questions_staff_all on public.questions for all to authenticated
  using (private.is_staff()) with check (private.is_staff());

-- secrets and Socratic prompts: staff only. Students get them through the API after the tutor session ends.
create policy secrets_staff_all on public.question_secrets for all to authenticated
  using (private.is_staff()) with check (private.is_staff());
create policy steps_staff_all on public.socratic_steps for all to authenticated
  using (private.is_staff()) with check (private.is_staff());

-- tests: students read published only; only staff write.
create policy tests_student_read on public.tests for select to authenticated
  using (published);
create policy tests_staff_all on public.tests for all to authenticated
  using (private.is_staff()) with check (private.is_staff());
create policy test_questions_read on public.test_questions for select to authenticated
  using (exists (select 1 from public.tests t where t.id = test_id and t.published) or private.is_staff());
create policy test_questions_staff_write on public.test_questions for all to authenticated
  using (private.is_staff()) with check (private.is_staff());

-- attempts: your own only. No insert/update policy: they are created and scored by start_attempt/submit_attempt.
create policy attempts_select on public.attempts for select to authenticated
  using (user_id = auth.uid() or private.is_admin());
create policy attempt_answers_select on public.attempt_answers for select to authenticated
  using (exists (select 1 from public.attempts a where a.id = attempt_id and (a.user_id = auth.uid() or private.is_admin())));

-- unlocks: read your own. Rows are inserted by the payment webhook (service role) or admin_grant_unlock only.
create policy unlocks_select on public.unlocks for select to authenticated
  using (user_id = auth.uid() or private.is_admin());

-- free explanations: read your own. Insert allowed only for yourself, only for a question you attempted;
-- the cap of two is enforced by the guard trigger so it also holds under concurrent requests.
create policy free_uses_select on public.free_explanation_uses for select to authenticated
  using (user_id = auth.uid() or private.is_admin());
create policy free_uses_insert on public.free_explanation_uses for insert to authenticated
  with check (user_id = auth.uid() and private.has_attempted(auth.uid(), question_id));

create policy revision_own on public.revision_items for all to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());

-- ---------------------------------------------------------------- grants
revoke all on all tables in schema public from anon, authenticated;
revoke all on all functions in schema public from public, anon, authenticated;

grant usage on schema private to authenticated;
grant execute on function private.app_role(), private.is_staff(), private.is_admin(), private.has_attempted(uuid, uuid)
  to authenticated;

grant select on public.profiles, public.questions, public.tests, public.test_questions, public.attempts,
                public.attempt_answers, public.unlocks, public.free_explanation_uses, public.revision_items
  to authenticated;
grant update (name, exam_year, language) on public.profiles to authenticated;
grant insert, delete on public.revision_items to authenticated;
grant insert on public.free_explanation_uses to authenticated;
grant select, insert, update, delete on public.question_secrets, public.socratic_steps to authenticated;
grant insert, update, delete on public.questions, public.tests, public.test_questions to authenticated;

grant execute on function
  public.complete_profile(text, int), public.start_attempt(uuid), public.submit_attempt(uuid, jsonb, jsonb),
  public.admin_upsert_question(jsonb), public.admin_get_question(uuid), public.admin_upsert_test(jsonb),
  public.admin_set_role(uuid, public.user_role), public.admin_grant_unlock(uuid, uuid)
  to authenticated;

-- ===== supabase/migrations/20260101000300_tutor_sessions.sql =====
-- Tutor sessions, AI usage logging and the single gate that decides who may open an explanation.
-- Sessions hold NO chat content (data minimisation): only counters and state.

create function private.tutor_seconds() returns int
language sql immutable as $$ select 120 $$; -- keep equal to TUTOR_SECONDS in shared/rules.js

create table public.tutor_sessions (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null references public.profiles (id) on delete cascade,
  question_id    uuid not null references public.questions (id) on delete cascade,
  test_id        uuid not null references public.tests (id) on delete cascade,
  access         text not null check (access in ('paid', 'free', 'staff')),
  status         text not null default 'active' check (status in ('active', 'finished')),
  finish_reason  text check (finish_reason in ('done', 'timeout', 'skip')),
  started_at     timestamptz not null default now(),
  finished_at    timestamptz,
  paused_ms      int not null default 0,   -- time spent waiting on the model; the 2:00 timer does not run during it
  turns          int not null default 0,
  hints          int not null default 0,
  step           smallint not null default 1,
  script_idx     smallint not null default 0,
  check ((status = 'finished') = (finish_reason is not null))
);
create unique index tutor_sessions_one_active on public.tutor_sessions (user_id, question_id) where status = 'active';
create index tutor_sessions_lookup on public.tutor_sessions (user_id, question_id, started_at desc);

-- Token-use log: counts and timings only, never prompts or replies.
create table public.ai_usage (
  id             bigint generated always as identity primary key,
  user_id        uuid not null references public.profiles (id) on delete cascade,
  question_id    uuid references public.questions (id) on delete set null,
  kind           text not null check (kind in ('turn', 'wrapup')),
  source         text not null check (source in ('claude', 'scripted', 'limited', 'error')),
  model          text,
  input_tokens   int not null default 0,
  output_tokens  int not null default 0,
  latency_ms     int not null default 0,
  created_at     timestamptz not null default now()
);
create index ai_usage_user_day on public.ai_usage (user_id, created_at desc);

alter table public.tutor_sessions enable row level security;
alter table public.ai_usage enable row level security;
create policy tutor_sessions_select on public.tutor_sessions for select to authenticated
  using (user_id = auth.uid() or private.is_admin());
create policy ai_usage_admin_select on public.ai_usage for select to authenticated
  using (private.is_admin());
revoke all on public.tutor_sessions, public.ai_usage from anon, authenticated;
grant select on public.tutor_sessions, public.ai_usage to authenticated;

-- The one entitlement gate. Called by the API (service connection) with the verified user id.
--   staff           -> access 'staff' (previewing, never consumes a free slot)
--   test unlocked   -> access 'paid'
--   already free    -> access 'free' (re-opening a question you already spent a slot on)
--   slot available  -> consumes a slot, access 'free'
--   otherwise       -> raises 'paywall'
-- It also requires a submitted attempt that contained the question, then creates or resumes the tutor session.
create function private.open_explanation(p_user uuid, p_attempt uuid, p_question uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_test uuid;
  v_role public.user_role;
  v_access text;
  v_used int;
  v_sess public.tutor_sessions%rowtype;
begin
  select test_id into v_test from public.attempts
   where id = p_attempt and user_id = p_user and submitted_at is not null;
  if v_test is null then raise exception 'attempt_not_found' using errcode = 'P0002'; end if;
  if not exists (select 1 from public.attempt_answers where attempt_id = p_attempt and question_id = p_question) then
    raise exception 'question_not_in_attempt' using errcode = 'P0002';
  end if;

  perform pg_advisory_xact_lock(hashtext('explain:' || p_user::text));

  select role into v_role from public.profiles where id = p_user;
  if v_role in ('teacher', 'admin') then
    v_access := 'staff';
  elsif exists (select 1 from public.unlocks u where u.user_id = p_user and u.test_id = v_test and u.revoked_at is null) then
    v_access := 'paid';
  elsif exists (select 1 from public.free_explanation_uses f where f.user_id = p_user and f.question_id = p_question) then
    v_access := 'free';
  elsif (select count(*) from public.free_explanation_uses f where f.user_id = p_user) < private.free_explanation_limit() then
    insert into public.free_explanation_uses (user_id, question_id) values (p_user, p_question);
    v_access := 'free';
  else
    raise exception 'paywall' using errcode = 'P0001', detail = v_test::text;
  end if;

  -- Resume the active session, else reuse a finished one (the student already earned the explanation), else start.
  select * into v_sess from public.tutor_sessions
   where user_id = p_user and question_id = p_question
   order by (status = 'active') desc, started_at desc limit 1;
  if not found then
    insert into public.tutor_sessions (user_id, question_id, test_id, access)
    values (p_user, p_question, v_test, v_access) returning * into v_sess;
  elsif v_sess.status = 'active' and v_sess.access <> v_access then
    update public.tutor_sessions set access = v_access where id = v_sess.id returning * into v_sess;
  end if;

  select count(*) into v_used from public.free_explanation_uses where user_id = p_user;
  return jsonb_build_object(
    'session_id', v_sess.id, 'test_id', v_test, 'access', v_access, 'status', v_sess.status, 'step', v_sess.step,
    'seconds_left', greatest(0, round(private.tutor_seconds() - extract(epoch from (now() - v_sess.started_at)) + v_sess.paused_ms / 1000.0))::int,
    'free_left', greatest(0, private.free_explanation_limit() - v_used));
end $$;

-- Does this user have paid access to the test that contains the question (any test they attempted)?
create function private.has_paid_access(p_user uuid, p_question uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1
    from public.attempts a
    join public.attempt_answers aa on aa.attempt_id = a.id
    join public.unlocks u on u.test_id = a.test_id and u.user_id = a.user_id and u.revoked_at is null
    where a.user_id = p_user and a.submitted_at is not null and aa.question_id = p_question
  )
$$;

-- Service-role only: nothing here is callable by clients.
revoke all on function private.open_explanation(uuid, uuid, uuid), private.has_paid_access(uuid, uuid) from public, anon, authenticated;

-- ===== supabase/migrations/20260101000400_entitlement_hardening.sql =====
-- Stage 3: free vs paid rules, enforced below the API as well.
-- The API calls private.open_explanation (security definer, service connection). These additions make sure that
-- even a client holding a valid user JWT and talking to PostgREST directly cannot get more than the rules allow.

-- 1. free_explanation_uses: a client may only insert a use for a question it attempted and cannot exceed the cap
--    (policy from the core migration + guard trigger). Clients can never update or delete uses (no grant).
-- 2. unlocks: no write grant for clients at all (already revoked); only service role / admin_grant_unlock write.
-- 3. tutor_sessions / ai_usage: select only; no write grant.

-- Convenience for the UI and for tests: what can this user do right now? (Read-only, own data only.)
create function public.my_entitlements() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'free_limit', private.free_explanation_limit(),
    'free_used', (select count(*) from public.free_explanation_uses f where f.user_id = auth.uid()),
    'unlocked_tests', coalesce((select jsonb_agg(u.test_id) from public.unlocks u where u.user_id = auth.uid() and u.revoked_at is null), '[]'::jsonb))
$$;
revoke all on function public.my_entitlements() from public, anon, authenticated;
grant execute on function public.my_entitlements() to authenticated;

-- Revoking an unlock (refunds, stage 5) must also stop paid access to explanations from being served.
-- private.open_explanation and private.has_paid_access already filter on revoked_at is null.

-- ===== supabase/migrations/20260101000500_storage_buckets.sql =====
-- Storage: a private bucket for explanation videos and a public bucket for question diagrams.
--
-- videos   PRIVATE. Only teachers/admins can read, upload, replace or delete objects. Students never get a direct
--          path: the API checks entitlement and the finished tutor session, then hands out a short-lived signed URL.
-- diagrams PUBLIC read (students need the picture during the test). Staff-only writes. Object names are random UUIDs
--          so draft diagrams are not guessable.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  ('videos', 'videos', false, 209715200, array['video/mp4']),
  ('diagrams', 'diagrams', true, 5242880, array['image/png', 'image/jpeg', 'image/webp'])
on conflict (id) do update
  set public = excluded.public, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

create policy videos_staff_all on storage.objects for all to authenticated
  using (bucket_id = 'videos' and private.is_staff())
  with check (bucket_id = 'videos' and private.is_staff());

create policy diagrams_staff_write on storage.objects for all to authenticated
  using (bucket_id = 'diagrams' and private.is_staff())
  with check (bucket_id = 'diagrams' and private.is_staff());
-- Public bucket objects are served without a policy; the policy below also lets signed-in users list them via the API.
create policy diagrams_read on storage.objects for select to anon, authenticated
  using (bucket_id = 'diagrams');

-- ===== supabase/migrations/20260101000600_payments.sql =====
-- Payments. Rows are written only by the API (service connection): order creation and the verified Razorpay webhook.
-- Students can read their own payments (payment history); admins can read all and flag refunds.

create table public.payments (
  id                  uuid primary key default gen_random_uuid(),
  user_id             uuid references public.profiles (id) on delete set null, -- kept (anonymised) if the account is deleted
  test_id             uuid references public.tests (id) on delete set null,
  amount_paise        int not null check (amount_paise > 0),
  currency            text not null default 'INR',
  status              text not null default 'created' check (status in ('created', 'paid', 'failed', 'refunded')),
  razorpay_order_id   text not null unique,
  razorpay_payment_id text unique,
  method              text,
  refund_flag         boolean not null default false,
  refund_note         text,
  refund_flagged_by   uuid references public.profiles (id) on delete set null,
  refund_flagged_at   timestamptz,
  refund_id           text,
  created_at          timestamptz not null default now(),
  paid_at             timestamptz,
  refunded_at         timestamptz
);
create index payments_user_idx on public.payments (user_id, created_at desc);
create index payments_status_idx on public.payments (status, created_at desc);

-- Link an unlock to the payment that created it.
alter table public.unlocks add column payment_id uuid references public.payments (id) on delete set null;

-- Processed webhook events, for idempotency (Razorpay retries deliveries).
create table public.payment_events (
  event_id    text primary key,
  event_type  text not null,
  created_at  timestamptz not null default now()
);

alter table public.payments enable row level security;
alter table public.payment_events enable row level security;
create policy payments_select on public.payments for select to authenticated
  using (user_id = auth.uid() or private.is_admin());
revoke all on public.payments, public.payment_events from anon, authenticated;
grant select on public.payments to authenticated;

-- Admin: flag (or clear) a payment for refund. Flagging does not move money or revoke access; the refund itself
-- is issued in the Razorpay dashboard. When Razorpay reports refund.processed the webhook marks it refunded and
-- revokes the unlock.
create function public.admin_flag_refund(p_payment uuid, p_flag boolean, p_note text default null) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not private.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  update public.payments
     set refund_flag = p_flag,
         refund_note = case when p_flag then left(btrim(coalesce(p_note, '')), 500) else null end,
         refund_flagged_by = case when p_flag then auth.uid() else null end,
         refund_flagged_at = case when p_flag then now() else null end
   where id = p_payment and status in ('paid', 'refunded');
  if not found then raise exception 'payment_not_found' using errcode = 'P0002'; end if;
end $$;
revoke all on function public.admin_flag_refund(uuid, boolean, text) from public, anon, authenticated;
grant execute on function public.admin_flag_refund(uuid, boolean, text) to authenticated;

-- Called by the webhook handler (service connection only), in one transaction per event.
-- Returns what happened so the API can log it. Idempotent on event id and on payment id.
create function private.apply_payment_captured(p_event text, p_order text, p_payment text, p_amount int, p_currency text, p_method text) returns text
language plpgsql security definer set search_path = '' as $$
declare
  v_pay public.payments%rowtype;
begin
  insert into public.payment_events (event_id, event_type) values (p_event, 'payment.captured') on conflict do nothing;
  if not found then return 'duplicate_event'; end if;

  select * into v_pay from public.payments where razorpay_order_id = p_order for update;
  if not found then delete from public.payment_events where event_id = p_event; return 'unknown_order'; end if;
  if v_pay.status in ('paid', 'refunded') then return 'already_paid'; end if;
  -- The webhook amount must equal what we asked Razorpay to charge for this order.
  if v_pay.amount_paise <> p_amount or v_pay.currency <> p_currency then return 'amount_mismatch'; end if;
  if v_pay.user_id is null or v_pay.test_id is null then return 'orphaned'; end if;

  update public.payments
     set status = 'paid', razorpay_payment_id = p_payment, method = p_method, paid_at = now()
   where id = v_pay.id;
  insert into public.unlocks (user_id, test_id, source, payment_id)
  values (v_pay.user_id, v_pay.test_id, 'payment', v_pay.id)
  on conflict (user_id, test_id) do update set revoked_at = null, payment_id = excluded.payment_id, source = 'payment';
  return 'unlocked';
end $$;

create function private.apply_payment_failed(p_event text, p_order text) returns text
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.payment_events (event_id, event_type) values (p_event, 'payment.failed') on conflict do nothing;
  if not found then return 'duplicate_event'; end if;
  update public.payments set status = 'failed' where razorpay_order_id = p_order and status = 'created';
  return 'failed';
end $$;

create function private.apply_refund_processed(p_event text, p_payment text, p_refund text) returns text
language plpgsql security definer set search_path = '' as $$
declare
  v_pay public.payments%rowtype;
begin
  insert into public.payment_events (event_id, event_type) values (p_event, 'refund.processed') on conflict do nothing;
  if not found then return 'duplicate_event'; end if;
  select * into v_pay from public.payments where razorpay_payment_id = p_payment for update;
  if not found then delete from public.payment_events where event_id = p_event; return 'unknown_payment'; end if;
  update public.payments set status = 'refunded', refund_id = p_refund, refunded_at = now() where id = v_pay.id;
  update public.unlocks set revoked_at = now() where payment_id = v_pay.id and revoked_at is null;
  return 'refunded';
end $$;

revoke all on function private.apply_payment_captured(text, text, text, int, text, text), private.apply_payment_failed(text, text),
  private.apply_refund_processed(text, text, text) from public, anon, authenticated;

-- ===== supabase/migrations/20260101000700_admin_analytics.sql =====
-- Real analytics for the admin screens. All functions are staff-only (teachers see content analytics,
-- only admins see revenue and user counts). They read submitted attempts and captured payments, nothing is invented.

-- Average score per test (submitted attempts only).
create function public.admin_test_stats() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not private.is_staff() then raise exception 'forbidden' using errcode = '42501'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'test_id', t.id, 'title', t.title, 'attempts', s.n, 'students', s.students,
      'avg_score', round(s.avg_score, 1), 'avg_max', s.avg_max, 'avg_pct', round(s.avg_score * 100.0 / nullif(s.avg_max, 0), 1),
      'avg_minutes', round(s.avg_seconds / 60.0, 1)) order by t.created_at)
    from public.tests t
    join lateral (
      select count(*)::int n, count(distinct a.user_id)::int students, avg(a.score)::numeric avg_score, avg(a.max_score)::numeric avg_max,
             avg((select sum(aa.time_seconds) from public.attempt_answers aa where aa.attempt_id = a.id))::numeric avg_seconds
      from public.attempts a where a.test_id = t.id and a.submitted_at is not null
    ) s on s.n > 0), '[]'::jsonb);
end $$;

-- Hardest questions: lowest share correct among those attempted. Needs a minimum number of answers to be meaningful.
create function public.admin_question_stats(p_min int default 1, p_limit int default 100) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not private.is_staff() then raise exception 'forbidden' using errcode = '42501'; end if;
  return coalesce((
    select jsonb_agg(r order by (r ->> 'pct_correct')::numeric asc, (r ->> 'answered')::int desc)
    from (
      select jsonb_build_object(
        'question_id', q.id, 'text', q.text, 'subject', q.subject, 'chapter', q.chapter,
        'shown', count(*)::int, 'answered', count(*) filter (where aa.selected is not null)::int,
        'correct', count(*) filter (where aa.is_correct)::int, 'skipped', count(*) filter (where aa.selected is null)::int,
        'pct_correct', round(100.0 * count(*) filter (where aa.is_correct) / nullif(count(*) filter (where aa.selected is not null), 0), 1),
        'avg_seconds', round(avg(aa.time_seconds), 0)) as r
      from public.attempt_answers aa
      join public.attempts a on a.id = aa.attempt_id and a.submitted_at is not null
      join public.questions q on q.id = aa.question_id
      group by q.id
      having count(*) filter (where aa.selected is not null) >= greatest(p_min, 1)
      limit greatest(p_limit, 1)
    ) x), '[]'::jsonb);
end $$;

-- Revenue from unlocks: captured payments, net of refunds, by month, plus totals. Admin only.
create function public.admin_revenue() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not private.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  return jsonb_build_object(
    'gross_paise', coalesce((select sum(amount_paise) from public.payments where status in ('paid', 'refunded')), 0),
    'refunded_paise', coalesce((select sum(amount_paise) from public.payments where status = 'refunded'), 0),
    'paid_count', (select count(*) from public.payments where status in ('paid', 'refunded')),
    'refund_flagged', (select count(*) from public.payments where refund_flag and status = 'paid'),
    'manual_unlocks', (select count(*) from public.unlocks where source = 'manual' and revoked_at is null),
    'by_month', coalesce((
      select jsonb_agg(jsonb_build_object('month', m, 'net_paise', net, 'count', n) order by m)
      from (select to_char(date_trunc('month', paid_at), 'YYYY-MM') m, sum(case when status = 'paid' then amount_paise else 0 end) net, count(*)::int n
              from public.payments where status in ('paid', 'refunded') and paid_at is not null group by 1) mm), '[]'::jsonb));
end $$;

-- Counts for the dashboard. Admin sees people counts; teachers get content counts only.
create function public.admin_overview() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not private.is_staff() then raise exception 'forbidden' using errcode = '42501'; end if;
  return jsonb_build_object(
    'tests', (select count(*) from public.tests),
    'questions', (select count(*) from public.questions),
    'published_questions', (select count(*) from public.questions where status = 'published'),
    'attempts', (select count(*) from public.attempts where submitted_at is not null),
    'students', case when private.is_admin() then (select count(*) from public.profiles where role = 'student') end,
    'active_unlocks', case when private.is_admin() then (select count(*) from public.unlocks where revoked_at is null) end);
end $$;

-- Users and plans (admin only). Phone numbers are masked in the result; admins who need the full number
-- can read it from Supabase directly, which is audited there.
create function public.admin_users() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not private.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', p.id, 'name', p.name, 'role', p.role,
      'phone', regexp_replace(coalesce(p.phone, ''), '^(\d{2})(\d{2})\d{4}(\d{4})$', '\1\2xxxx\3'),
      'exam_year', p.exam_year, 'joined', p.created_at,
      'unlocked_tests', (select count(*) from public.unlocks u where u.user_id = p.id and u.revoked_at is null),
      'attempts', (select count(*) from public.attempts a where a.user_id = p.id and a.submitted_at is not null)) order by p.created_at desc)
    from (select * from public.profiles order by created_at desc limit 500) p), '[]'::jsonb);
end $$;

revoke all on function public.admin_test_stats(), public.admin_question_stats(int, int), public.admin_revenue(),
  public.admin_overview(), public.admin_users() from public, anon, authenticated;
grant execute on function public.admin_test_stats(), public.admin_question_stats(int, int), public.admin_revenue(),
  public.admin_overview(), public.admin_users() to authenticated;

-- ===== supabase/migrations/20260101000800_privacy_consent.sql =====
-- Privacy: under-18 handling (parental consent), minimal data, and data retention.
--
-- Data we keep per student: phone (login), name, exam year, birth YEAR (not the full date), is_minor, language.
-- For minors we also keep a consent record (guardian name, guardian phone, policy version, time).
-- Tutor chats are never stored. ai_usage keeps counts only. Both are purged on a schedule below.

alter table public.profiles
  add column birth_year int check (birth_year between 1950 and 2030),
  add column is_minor boolean not null default false;

create table public.parental_consents (
  user_id         uuid primary key references public.profiles (id) on delete cascade,
  guardian_name   text not null check (char_length(guardian_name) between 2 and 80),
  guardian_phone  text not null check (guardian_phone ~ '^[6-9][0-9]{9}$'),
  relationship    text not null check (relationship in ('mother', 'father', 'legal guardian')),
  policy_version  text not null,
  consented_at    timestamptz not null default now()
);
alter table public.parental_consents enable row level security;
create policy consents_select on public.parental_consents for select to authenticated
  using (user_id = auth.uid() or private.is_admin());
revoke all on public.parental_consents from anon, authenticated;
grant select on public.parental_consents to authenticated;

-- Sign-up completion, replacing complete_profile. The server decides is_minor from the birth date it was given;
-- the full date is not stored. A minor cannot finish sign-up without a guardian consent record.
-- (The age is computed as of today; a person is a minor until their 18th birthday.)
create function public.complete_signup(
  p_name text, p_exam_year int, p_birth_date date,
  p_guardian_name text default null, p_guardian_phone text default null, p_relationship text default null,
  p_consent boolean default false, p_policy_version text default null
) returns void
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  v_age int;
  v_minor boolean;
begin
  if v_uid is null then raise exception 'not_authenticated' using errcode = '42501'; end if;
  if p_birth_date is null or p_birth_date > current_date or p_birth_date < date '1950-01-01' then
    raise exception 'invalid_birth_date' using errcode = 'P0001';
  end if;
  if btrim(coalesce(p_name, '')) = '' then raise exception 'name_required' using errcode = 'P0001'; end if;
  v_age := extract(year from age(current_date, p_birth_date));
  if v_age < 13 then raise exception 'too_young' using errcode = 'P0001'; end if; -- minimum age 13 (MIN_AGE in src/privacy.js)
  v_minor := v_age < 18;
  if not p_consent then raise exception 'policy_consent_required' using errcode = 'P0001'; end if; -- accepted the privacy policy
  if v_minor and (btrim(coalesce(p_guardian_name, '')) = '' or coalesce(p_guardian_phone, '') !~ '^[6-9][0-9]{9}$'
                  or p_relationship not in ('mother', 'father', 'legal guardian')) then
    raise exception 'guardian_consent_required' using errcode = 'P0001';
  end if;

  update public.profiles
     set name = left(btrim(p_name), 80), exam_year = p_exam_year, birth_year = extract(year from p_birth_date)::int,
         is_minor = v_minor, onboarded = true
   where id = v_uid;

  if v_minor then
    insert into public.parental_consents (user_id, guardian_name, guardian_phone, relationship, policy_version)
    values (v_uid, left(btrim(p_guardian_name), 80), p_guardian_phone, p_relationship, coalesce(p_policy_version, 'unknown'))
    on conflict (user_id) do update
       set guardian_name = excluded.guardian_name, guardian_phone = excluded.guardian_phone,
           relationship = excluded.relationship, policy_version = excluded.policy_version, consented_at = now();
  end if;
end $$;
revoke all on function public.complete_signup(text, int, date, text, text, text, boolean, text) from public, anon, authenticated;
grant execute on function public.complete_signup(text, int, date, text, text, text, boolean, text) to authenticated;

-- Retired: the old sign-up function skipped the age and consent step.
drop function public.complete_profile(text, int);

-- Data retention. Run daily (pg_cron on Supabase: select cron.schedule('bioprep-purge', '17 3 * * *', 'select public.purge_old_data()')).
--   * tutor session rows (counters only) older than 30 days
--   * AI usage rows older than 90 days
--   * attempts that were started but never submitted, older than 7 days
--   * processed webhook event ids older than 60 days
create function public.purge_old_data() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare a int; b int; c int; d int;
begin
  delete from public.tutor_sessions where started_at < now() - interval '30 days'; get diagnostics a = row_count;
  delete from public.ai_usage where created_at < now() - interval '90 days'; get diagnostics b = row_count;
  delete from public.attempts where submitted_at is null and started_at < now() - interval '7 days'; get diagnostics c = row_count;
  delete from public.payment_events where created_at < now() - interval '60 days'; get diagnostics d = row_count;
  return jsonb_build_object('tutor_sessions', a, 'ai_usage', b, 'abandoned_attempts', c, 'payment_events', d);
end $$;
revoke all on function public.purge_old_data() from public, anon, authenticated;

-- Right to erasure. Called by the API after it has deleted the auth user (which cascades to profile, attempts,
-- unlocks, free uses, revision items, consent, tutor sessions and usage). Payment rows are kept for the
-- accounting records the law requires, but are detached from the person (user_id becomes null via ON DELETE SET NULL).
-- Nothing else to do here: this comment documents the behaviour and tests/db/privacy.test.js enforces it.
